// TEN-225 item 2 — offline tests for the RabbitMQ consumer. No broker, no
// database, no network.
//
// THE CENTRAL TEST IS THE KEY. Everything else here is ordinary. The row key is
// the one thing whose failure is silent and expensive: a Node key that disagrees
// with the sweep's Python key turns every streamed row into a "new" row, doubles
// the archive, and breaks first-sighting-wins — while reporting a busy market.
// So the key is tested against a corpus generated by the REAL Python function
// (gen-key-corpus.py), not against a fixture I typed out and then matched the
// Node side to, which would only test my own consistency.
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import {
  pyStr, observationKey, parseWithLexemes, hasSourceAccess, assertSourceAccess, KEY_FIELDS,
} from './py_str.mjs';
import {
  backoffFor, BACKOFF_MS, rowsFromMessage, heartbeatRow, livenessAlert, gapRecord,
  HEARTBEAT_EVERY_MS, TABLE_OBS,
} from './consumer.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const FAILED = [];
const check = (name, cond, detail = '') => {
  console.log(`  ${cond ? 'ok  ' : 'FAIL'} ${name}${detail ? '   ' + detail : ''}`);
  if (!cond) FAILED.push(name);
};

console.log('\nruntime capability — fail loud, never fall back');
check('this runtime has JSON.parse source-text access', hasSourceAccess());
check('assertSourceAccess passes here', (() => { try { assertSourceAccess(); return true; } catch (e) { return false; } })());
// A silent fallback to String() for numbers IS the archive-doubling failure, and
// it would present as a healthy worker writing lots of new rows. So the worker
// must refuse to start rather than degrade. Proven by the message, since the
// runtime under test supports it.
check('...and refusing is what it does, not degrading',
      /Refusing to start/.test(String((() => { try { throw new Error(''); } catch (e) {}
        // eslint-disable-next-line no-new-func
        return assertSourceAccess.toString(); })())));

console.log('\npyStr — Python spelling, which is where a naive port breaks');
check('None, not null', pyStr(null) === 'None' && pyStr(undefined) === 'None');
check('True/False, not true/false', pyStr(true) === 'True' && pyStr(false) === 'False');
check('a string is itself', pyStr('1.69') === '1.69');
check('...and JS would have said "null"/"true", which is the whole point',
      String(null) === 'null' && String(true) === 'true');

console.log('\nobservation_key — against the corpus the REAL Python function produced');
const corpusPath = join(HERE, 'key-corpus.json');
// A missing corpus must FAIL, not skip. A skipped key test on a build whose key
// is wrong reads exactly like a passing one.
check('the corpus exists (regenerate with gen-key-corpus.py)', existsSync(corpusPath));
if (existsSync(corpusPath)) {
  const corpus = JSON.parse(readFileSync(corpusPath, 'utf8'));
  check('the corpus is not empty — an empty corpus passes every key test',
        corpus.length >= 8, `n=${corpus.length}`);
  let agree = 0; const disagree = [];
  for (const c of corpus) {
    // The corpus carries RAW JSON TEXT, not an object. Re-serialising a parsed
    // object here would turn 2.0 into 2 before the consumer saw it — the test
    // would destroy the exact lexeme it exists to check, and fail against
    // correct code. (It did, on case 3.)
    const text = c.row_json;
    const parsed = parseWithLexemes(text);
    const got = observationKey(parsed);
    if (got === c.key) agree += 1; else disagree.push({ want: c.key, got });
  }
  check(`every corpus row keys byte-identically to Python (n=${corpus.length})`,
        disagree.length === 0,
        disagree.length ? `\n      want ${disagree[0].want}\n      got  ${disagree[0].got}` : `${agree}/${corpus.length}`);

  // THE CONTROL. Without it "0 disagreements" would also pass on a corpus of
  // rows that happen to contain no divergent value — and then the test would be
  // certifying nothing. A naive String()-based key MUST disagree, or the corpus
  // is not exercising the cases this exists for.
  const naiveKey = row => KEY_FIELDS.map(f => String(row[f])).join('|');
  let naiveDisagree = 0;
  for (const c of corpus) if (naiveKey(JSON.parse(c.row_json)) !== c.key) naiveDisagree += 1;
  check('CONTROL: a naive String() key disagrees on the corpus, so the corpus bites',
        naiveDisagree >= corpus.length - 1, `${naiveDisagree}/${corpus.length} differ`);
}

console.log('\nthe integral-float case, which no post-parse fix can reach');
{
  const text = '{"fixture_id":9,"price_decimal":2.0}';
  const k = observationKey(parseWithLexemes(text));
  check('2.0 keys as "2.0" (Python), not "2" (JS)', k.includes('|2.0'), k);
  check('...and an ordinary JSON.parse cannot tell 2 from 2.0',
        JSON.parse('{"a":2.0}').a === JSON.parse('{"a":2}').a);
}

console.log('\nrowsFromMessage — envelopes, and never throwing on a stream');
{
  const now = '2026-09-21T03:00:00.000Z';
  const one = rowsFromMessage('{"fixture_id":1,"price_decimal":1.5}', now);
  check('a bare row is accepted', one.length === 1 && one[0].fixture_id === 1);
  check('...and carries a row_key and the stream provenance',
        !!one[0].row_key && one[0].sweep_id === 'stream' && one[0].observed_at === now);
  check('the REST envelope is accepted',
        rowsFromMessage('{"code":200,"result":[{"fixture_id":2},{"fixture_id":3}]}', now).length === 2);
  check('a bare array is accepted', rowsFromMessage('[{"fixture_id":4}]', now).length === 1);
  const st = {};
  check('malformed JSON returns [] and does NOT throw — one bad message must not '
        + 'kill the consumer and stop every other message',
        rowsFromMessage('{not json', now, st).length === 0);
  check('...and it is COUNTED, so a schema change is visible on the heartbeat '
        + 'rather than looking like a quiet market', st.unreadable === 1);
  const st2 = {};
  check('an unrecognised envelope is counted too, not guessed at',
        rowsFromMessage('{"something":"else"}', now, st2).length === 0 && st2.unreadable === 1);
  // Multi-row messages must key each row from ITS OWN lexemes.
  const multi = rowsFromMessage('{"result":[{"fixture_id":1,"price_decimal":2.0},{"fixture_id":2,"price_decimal":2}]}', now);
  check('in a multi-row message each row keys from its own lexeme (2.0 vs 2)',
        multi[0].row_key !== multi[1].row_key
        && multi[0].row_key.includes('|2.0') && multi[1].row_key.includes('|2|'),
        `${multi[0].row_key} vs ${multi[1].row_key}`);
}

console.log('\nbackoff — bounded, jittered, and never faster than 250ms');
{
  const lo = backoffFor(0, () => 0), hi = backoffFor(99, () => 1);
  check('the first retry is around a second', lo >= 250 && lo <= 1200, `${lo}ms`);
  check('it caps at 60s however many attempts', hi <= 60_000, `${hi}ms`);
  check('an attempt past the end of the ladder does not crash or go to zero',
        backoffFor(1000) >= 250);
  let min = Infinity, max = 0;
  for (let i = 0; i < 400; i++) { const v = backoffFor(2, Math.random); min = Math.min(min, v); max = Math.max(max, v); }
  check('the 5s rung jitters rather than synchronising a reconnect storm',
        min < max && min >= 250, `${min}..${max}ms`);
  check('the ladder is monotone', BACKOFF_MS.every((v, i) => i === 0 || v >= BACKOFF_MS[i - 1]));
}

console.log('\nthe gap record — a blind window is reportable, not merely felt');
{
  const g = gapRecord(Date.parse('2026-09-21T03:00:00Z'), Date.parse('2026-09-21T03:04:30Z'));
  check('start, end and duration', g.duration_seconds === 270
        && g.start === '2026-09-21T03:00:00.000Z' && g.end === '2026-09-21T03:04:30.000Z');
}

console.log('\nheartbeat + liveness — the failure the founder named');
{
  const now = Date.parse('2026-09-21T03:00:00Z');
  const hbOk = heartbeatRow({ connected: true, sinceLastBeat: 12, rowsSinceLastBeat: 40,
                              lastMessageAt: now - 5_000, reconnects: 1 }, now);
  check('the beat cadence is the ruled 60s', HEARTBEAT_EVERY_MS === 60_000);
  check('counts are SINCE THE LAST BEAT, not cumulative — a cumulative counter '
        + 'cannot answer "is the channel delivering right now"',
        hbOk.messages_since_last_beat === 12 && hbOk.rows_written_since_last_beat === 40);
  check('a healthy worker raises nothing', livenessAlert(hbOk, { expectNearStart: true }, now) === null);

  const stale = heartbeatRow({ connected: true, lastMessageAt: now - 5_000 },
                             now - 10 * 60_000);
  check('a stale heartbeat means the worker is not running',
        /not running/.test(livenessAlert(stale, {}, now) || ''));

  const down = heartbeatRow({ connected: false, lastMessageAt: now - 5_000 }, now);
  check('disconnected is reported as disconnected',
        /NOT connected/.test(livenessAlert(down, {}, now) || ''));

  // ⚠️ THE ONE THAT MATTERS. Connected, beating, and delivering nothing.
  const silent = heartbeatRow({ connected: true, lastMessageAt: now - 20 * 60_000 }, now);
  check('connected-but-silent raises NOTHING when no fixture is near the off — '
        + 'that really is a quiet market',
        livenessAlert(silent, { expectNearStart: false }, now) === null);
  check('...and DOES raise when a fixture is inside the dense band, which is the '
        + 'failure "that gets missed"',
        /silent for/.test(livenessAlert(silent, { expectNearStart: true }, now) || ''));
  const never = heartbeatRow({ connected: true, lastMessageAt: null }, now);
  check('a worker that has NEVER received a message is caught too — the first '
        + 'deploy of a mis-bound queue looks exactly like a quiet Sunday',
        /NEVER received/.test(livenessAlert(never, { expectNearStart: true }, now) || ''));
}

console.log('\nsame tables, new writer (founder 2(b))');
check('it writes the sweep\'s observation table, not a stream-only one',
      TABLE_OBS === 'kibl_line_observations');
{
  // ⚠️ COMMENTS STRIPPED BEFORE THE SCAN. The first cut went red because the
  // file's own explanatory comment says "no code here that DISABLES... the
  // sweep" — the assertion matched the word inside the sentence promising the
  // opposite. Same defect class as the column-name-in-a-comment match on
  // 2026-09-18; an assertion that reads prose is not reading code.
  const src = readFileSync(join(HERE, 'consumer.mjs'), 'utf8')
    .replace(/\/\*[\s\S]*?\*\//g, ' ')
    .split('\n').map(l => l.replace(/(^|\s)\/\/.*$/, '')).join('\n');
  check('the insert uses the sweep\'s conflict target and ignore-duplicates, so a '
        + 'row seen by BOTH writers is stored once',
        /on_conflict=row_key/.test(src) && /resolution=ignore-duplicates/.test(src));
  // (d) The sweep is the backstop. A stream that can stand the poller down turns
  // one outage into two, so there must be no such code path.
  check('nothing here can disable or throttle the sweep (founder 2(d))',
        !/unschedule|cadence_gate=false|disable/i.test(src));
}

console.log();
if (FAILED.length) { console.log(`FAILED ${FAILED.length}: ${JSON.stringify(FAILED)}`); process.exit(1); }
console.log('all kibl-stream offline tests passed');
